From e66c4b3da26c8c595405dc27f6d9a188f72f85f6 Mon Sep 17 00:00:00 2001
From: Jason Chu <jchu@xentac.net>
Date: Sun, 5 Jun 2016 22:57:48 +0000
Subject: [PATCH 01/10] Make aside menu hidable when screen is less than 768px

---
 fava/static/javascript/main.js |  7 +++++
 fava/static/sass/_base.scss    | 47 ++++++++++++++++++++++++++++++++--
 fava/static/sass/_editor.scss  | 11 +++++++-
 fava/templates/_layout.html    |  4 +++
 4 files changed, 66 insertions(+), 3 deletions(-)

diff --git a/fava/static/javascript/main.js b/fava/static/javascript/main.js
index 6aeeb797c..013231aab 100644
--- a/fava/static/javascript/main.js
+++ b/fava/static/javascript/main.js
@@ -55,4 +55,11 @@ $(document).ready(() => {
       $('.overlay-wrapper').hide();
     }
   });
+
+  $('#aside_button').click((e) => {
+    e.preventDefault();
+    $("aside").toggleClass("active");
+    $("#aside_button").toggleClass("active");
+    return false;
+  });
 });
diff --git a/fava/static/sass/_base.scss b/fava/static/sass/_base.scss
index 842daed30..b900f528e 100644
--- a/fava/static/sass/_base.scss
+++ b/fava/static/sass/_base.scss
@@ -138,7 +138,7 @@ $header_height: 50px;
 $aside_width: 160px;

 body {
-    padding: $header_height 0 0 $aside_width;
+    padding: $header_height 0 0 0;
 }

 header {
@@ -218,12 +218,36 @@ header {
     }
 }

+#aside_button {
+    position: fixed;
+    top: $header_height;
+    left: 0px;
+    height: 32px;
+    width: 32px;
+    background-color: $color_sidebar_background;
+    border-style: solid;
+    border-color: darken($color_sidebar_background, 16);
+    border-width: 0 1px 1px 0;
+    z-index: 1000;
+    display: block;
+}
+
+#aside_button.active {
+    left: $aside_width;
+}
+
+#aside_button svg {
+    height: 100%;
+    width: 100%;
+}
+
 aside {
     position: fixed;
-    top: 50px;
+    top: $header_height;
     bottom: 0;
     left: 0;
     padding-top: 1em;
+    margin-left: -$aside_width;
     flex-shrink: 0;
     width: $aside_width;
     color: $color_sidebar_text;
@@ -231,6 +255,7 @@ aside {
     background-color: $color_sidebar_background;
     overflow-y: auto;
     @include scrollbar(.5em, darken($color_sidebar_background, 30), transparent);
+    z-index: 1000;

     h3 {
         text-transform: uppercase;
@@ -299,6 +324,9 @@ aside {
         }
     }
 }
+aside.active {
+    margin-left: 0;
+}


 article {
@@ -594,3 +622,18 @@ table.queryresults {
         margin-left: 3px;
     }
 }
+
+/* Modifications for ipad */
+@media (min-width: 768px) {
+    body {
+        padding: $header_height 0 0 $aside_width;
+    }
+
+    aside {
+        margin-left: 0;
+    }
+    #aside_button {
+        display: none;
+    }
+}
+
diff --git a/fava/static/sass/_editor.scss b/fava/static/sass/_editor.scss
index a0c7cdb25..eeacfacbe 100644
--- a/fava/static/sass/_editor.scss
+++ b/fava/static/sass/_editor.scss
@@ -18,7 +18,7 @@ article#page-source {

     div.editor {
         position: fixed;
-        left: $aside_width;
+        left: 0;
         top: $header_height + 40px;
         right: 0;
         bottom: 0;
@@ -100,3 +100,12 @@ div.editor-wrapper {
         font: 13px $font_family_editor;
     }
 }
+
+/* Modifications for ipad */
+@media (min-width: 768px) {
+article#page-source {
+    div.editor {
+        left: $aside_width;
+    }
+}
+}
diff --git a/fava/templates/_layout.html b/fava/templates/_layout.html
index 463151de7..1321e5578 100644
--- a/fava/templates/_layout.html
+++ b/fava/templates/_layout.html
@@ -25,6 +25,7 @@
 <!doctype html>
 <html>
 <head>
+    <meta name="viewport" content="width=device-width, initial-scale=1">
     <link rel="shortcut icon" href="{{ url_for('static', filename='images/favicon.ico') }}">
     <link rel="stylesheet" href="{{ url_for('static', filename='gen/theme_' + config['theme'] + '.css') }}">
     <title>{{ short_title }} - {{ api.title }}</title>
@@ -53,6 +54,9 @@ <h1 class="site-name">{{ api.title or 'fava' }}{{ ' ▾' if config['APIS']|lengt
         </nav>
         {% endif %}
     </header>
+    <a href="#" id="aside_button">
+        <svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" enable-background="new 0 0 24 24" id="Layer_1" version="1.0" viewBox="0 0 24 24" xml:space="preserve"><circle cx="12" cy="12" r="2"/><circle cx="12" cy="5" r="2"/><circle cx="12" cy="19" r="2"/></svg>
+    </a>
     <aside>
         {% if api.sidebar_links %}
             <h3>{{ _('Custom Links') }}</h3>

From 575f6acad1436a6c2cc83c3ec276a11c88c9278a Mon Sep 17 00:00:00 2001
From: Jason Chu <jchu@xentac.net>
Date: Sun, 5 Jun 2016 22:58:20 +0000
Subject: [PATCH 02/10] Make two columns into single columns when screen is
 less than 1280px

---
 fava/static/sass/_base.scss | 29 +++++++++++++++++------------
 1 file changed, 17 insertions(+), 12 deletions(-)

diff --git a/fava/static/sass/_base.scss b/fava/static/sass/_base.scss
index b900f528e..0bf9ef306 100644
--- a/fava/static/sass/_base.scss
+++ b/fava/static/sass/_base.scss
@@ -59,7 +59,6 @@ body {
     font-weight: 400;
     font-size: 14px;
     height: 100%;
-    min-width: 1235px;
     color: $color_text;
     background: $color_background;
 }
@@ -448,23 +447,13 @@ kbd {

 .halfleft,
 .halfright {
-    width: 50%;
+    width: 100%;

     h3 {
         text-align: center;
     }
 }

-.halfleft {
-    float: left;
-    padding-right: 10px;
-}
-
-.halfright {
-    float: right;
-    padding-left: 10px;
-}
-
 .left {
     float: left;
 }
@@ -637,3 +626,19 @@ table.queryresults {
     }
 }

+@media (min-width: 1280px) {
+    .halfleft,
+    .halfright {
+        width: 50%;
+    }
+
+    .halfleft {
+        float: left;
+        padding-right: 10px;
+    }
+
+    .halfright {
+        float: right;
+        padding-left: 10px;
+    }
+}

From f54c050572d857b065bb26a04704800c6a2bcc76 Mon Sep 17 00:00:00 2001
From: Jason Chu <jchu@xentac.net>
Date: Mon, 6 Jun 2016 02:15:41 +0000
Subject: [PATCH 03/10] Reduce each column width if there are more currencies

Supports 1 to 5 operating currencies, though anything more than 2 will be
fairly squished.
---
 fava/application.py               |  1 +
 fava/static/sass/_base.scss       |  1 +
 fava/static/sass/_tree-table.scss | 18 ++++++++++++++++++
 fava/templates/_tree_table.html   |  2 +-
 4 files changed, 21 insertions(+), 1 deletion(-)

diff --git a/fava/application.py b/fava/application.py
index 80060c61e..6d6d6dcdd 100644
--- a/fava/application.py
+++ b/fava/application.py
@@ -375,6 +375,7 @@ def url_for_source(**kwargs):
                 url_for_source=url_for_source,
                 api=g.api,
                 operating_currencies=g.api.options['operating_currency'],
+                num_currencies=len(g.api.options['operating_currency']),
                 today=datetime.now().strftime('%Y-%m-%d'),
                 interval=request.args.get('interval',
                                           app.config['interval']),)
diff --git a/fava/static/sass/_base.scss b/fava/static/sass/_base.scss
index 0bf9ef306..826a44937 100644
--- a/fava/static/sass/_base.scss
+++ b/fava/static/sass/_base.scss
@@ -59,6 +59,7 @@ body {
     font-weight: 400;
     font-size: 14px;
     height: 100%;
+    min-width: 560px;
     color: $color_text;
     background: $color_background;
 }
diff --git a/fava/static/sass/_tree-table.scss b/fava/static/sass/_tree-table.scss
index 01bebe2ab..92b329db2 100644
--- a/fava/static/sass/_tree-table.scss
+++ b/fava/static/sass/_tree-table.scss
@@ -136,3 +136,21 @@ ol.tree-table {
         &.budget-zero     { color: $color_budget_zero; }
     }
 }
+
+@for $i from 1 through 5 {
+    $num_fraction: 1rem * (1-(($i - 1)/10));
+    ol.tree-table.currencies#{$i} {
+       p > span {
+            &.num-header,
+            &.num {
+                width: 20rem / ($i+1);
+                font-size: $num_fraction;
+            }
+            &.other-header,
+            &.other {
+                width: 20rem / ($i+1) + 3rem;
+                font-size: $num_fraction;
+            }
+       }
+    }
+}
diff --git a/fava/templates/_tree_table.html b/fava/templates/_tree_table.html
index 531867774..e00012bad 100644
--- a/fava/templates/_tree_table.html
+++ b/fava/templates/_tree_table.html
@@ -5,7 +5,7 @@ <h3>{{ table_title }}</h3>

 {% set show_other_column = (operating_currencies|sort != api.options['commodities']|list|sort) %}

-<ol class="tree-table">
+<ol class="tree-table currencies{{ num_currencies }}">
     <li class="head">
         <p>
         <span class="account"><span>{{ _('Account') }}</span><a href="" class="expand-all hidden" title="{{ _('Expand all accounts') }}">{{ _('Expand all') }}</a></span>

